from pathlib import Path
import base64

ROOT = Path.cwd()

def write(path, encoded):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(base64.b64decode(encoded).decode("utf-8").strip() + "\n", encoding="utf-8")

def main():
    options = ROOT / "CVIS.Playwright.NUnitCompat" / "Reporting" / "CPNReportOptions.cs"
    if options.exists():
        text = options.read_text(encoding="utf-8")
        text = text.replace('public string JsonFileName { get; init; } = "cpn-report.json";',
                            'public string JsonFileName { get; init; } = "cpn-lifecycle-report.json";')
        text = text.replace('public string HtmlFileName { get; init; } = "cpn-report.html";',
                            'public string HtmlFileName { get; init; } = "cpn-lifecycle-report.html";')
        options.write_text(text, encoding="utf-8")

    write(ROOT / "scripts" / "merge-nunitxml-into-cpn-report.ps1", "")
    write(ROOT / "scripts" / "run-cvis-automation-reporting-local.ps1", "")
    write(ROOT / "scripts" / "run-cpn-reporting-local.ps1", "")
    write(ROOT / "README_CPN_FULL_VS_LIFECYCLE_REPORTS.md", "")

    print("Separated lifecycle report from full report.")
    print("Open TestResults\\CPN\\cpn-report.html for all tests.")

if __name__ == "__main__":
    main()
